INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','punctuation-clauses','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"punctuation-clauses","title":"Punctuation, sentence boundaries and direct speech","level":"B1","order":57,"summary":"Use punctuation to show clause relationships, possession, quotation and sentence boundaries.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Independent clauses need a real boundary","Colons and introductory material","Direct speech","Apostrophes and capitals"],"rules":[{"title":"Independent clauses need a real boundary","explanation":"A comma alone does not normally join two independent clauses in formal prose. Use a full stop, a semicolon, or a comma with a suitable coordinating conjunction. A semicolon joins closely related main clauses without a conjunction.","pattern":"The train stopped**;** we got off.","commonMistakes":["The train stopped, we got off is a comma splice in ordinary formal writing."],"examples":["Choose punctuation that joins two main clauses without a conjunction: “We prepared the visitor guide **;** the supervisor thanked us.”","Choose punctuation that joins two main clauses without a conjunction: “We restored the old portrait **;** the supervisor thanked us.”"],"skill":"form"},{"title":"Colons and introductory material","explanation":"A colon can introduce an explanation or list after a complete clause. A comma commonly follows an introductory subordinate clause or a long introductory adverbial. A dash can mark a break or inserted explanation, with conventions varying by style.","pattern":"We need three things**:** paper, ink and time.","commonMistakes":["Do not routinely put a colon between a verb and its object: We need: paper is usually unnecessary punctuation."],"examples":["Where should the comma go in “After we prepared the visitor guide we rested”? → **After we prepared the visitor guide, we rested.**","Where should the comma go in “After we restored the old portrait we rested”? → **After we restored the old portrait, we rested.**"],"skill":"meaning"},{"title":"Direct speech","explanation":"Quotation marks show exact spoken or written words. A reporting clause can introduce the quotation with a comma. Capitalise the beginning of a full quoted sentence. Single versus double quotation marks and some punctuation placement vary by house style.","pattern":"She said, **“Please wait.”**","commonMistakes":["Reported speech normally removes quotation marks because it does not claim the same exact wording."],"examples":["Choose a correctly introduced direct instruction to prepare the visitor guide. → **She said, “Prepare the visitor guide.”**","Choose a correctly introduced direct instruction to restore the old portrait. → **She said, “Restore the old portrait.”**"],"skill":"contrast"},{"title":"Apostrophes and capitals","explanation":"Use apostrophes for contractions and possession, not ordinary plurals. Its is possessive; it’s means it is or it has. Capitalise sentence openings, the pronoun I and proper names, including languages and weekdays.","pattern":"**It’s** Tuesday. / The dog lost **its** collar.","commonMistakes":["Quotation style varies, but the distinction between its and it’s is grammatical rather than an optional style choice."],"examples":["“**It’s** time to prepare the visitor guide.” Choose the contraction meaning “it is”.","“**It’s** time to restore the old portrait.” Choose the contraction meaning “it is”."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Use punctuation to show clause relationships, possession, quotation and sentence boundaries.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Independent clauses need a real boundary","explanation":"A comma alone does not normally join two independent clauses in formal prose. Use a full stop, a semicolon, or a comma with a suitable coordinating conjunction. A semicolon joins closely related main clauses without a conjunction.","pattern":"The train stopped**;** we got off.","commonMistakes":["The train stopped, we got off is a comma splice in ordinary formal writing."],"examples":["Choose punctuation that joins two main clauses without a conjunction: “We prepared the visitor guide **;** the supervisor thanked us.”","Choose punctuation that joins two main clauses without a conjunction: “We restored the old portrait **;** the supervisor thanked us.”"],"skill":"form","id":"punctuation-clauses-foundation-1","domain":"punctuation","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Colons and introductory material","explanation":"A colon can introduce an explanation or list after a complete clause. A comma commonly follows an introductory subordinate clause or a long introductory adverbial. A dash can mark a break or inserted explanation, with conventions varying by style.","pattern":"We need three things**:** paper, ink and time.","commonMistakes":["Do not routinely put a colon between a verb and its object: We need: paper is usually unnecessary punctuation."],"examples":["Where should the comma go in “After we prepared the visitor guide we rested”? → **After we prepared the visitor guide, we rested.**","Where should the comma go in “After we restored the old portrait we rested”? → **After we restored the old portrait, we rested.**"],"skill":"meaning","id":"punctuation-clauses-foundation-2","domain":"punctuation","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Direct speech","explanation":"Quotation marks show exact spoken or written words. A reporting clause can introduce the quotation with a comma. Capitalise the beginning of a full quoted sentence. Single versus double quotation marks and some punctuation placement vary by house style.","pattern":"She said, **“Please wait.”**","commonMistakes":["Reported speech normally removes quotation marks because it does not claim the same exact wording."],"examples":["Choose a correctly introduced direct instruction to prepare the visitor guide. → **She said, “Prepare the visitor guide.”**","Choose a correctly introduced direct instruction to restore the old portrait. → **She said, “Restore the old portrait.”**"],"skill":"contrast","id":"punctuation-clauses-foundation-3","domain":"punctuation","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Apostrophes and capitals","explanation":"Use apostrophes for contractions and possession, not ordinary plurals. Its is possessive; it’s means it is or it has. Capitalise sentence openings, the pronoun I and proper names, including languages and weekdays.","pattern":"**It’s** Tuesday. / The dog lost **its** collar.","commonMistakes":["Quotation style varies, but the distinction between its and it’s is grammatical rather than an optional style choice."],"examples":["“**It’s** time to prepare the visitor guide.” Choose the contraction meaning “it is”.","“**It’s** time to restore the old portrait.” Choose the contraction meaning “it is”."],"skill":"application","id":"punctuation-clauses-foundation-4","domain":"punctuation","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"domain":"punctuation","id":"sentence-boundaries-fragments","title":"Full stops, fragments and comma splices","explanation":"A full stop normally ends an independent written sentence. A comma alone does not ordinarily join two independent clauses in formal edited prose. A fragment lacks the structure expected of a full sentence, but fragments can be deliberate in dialogue, headings or literary writing. Choose punctuation for the construction and the intended register.","pattern":"We waited. **The bus never came.**","examples":["We waited, **but** the bus never came.","**Because it was late**, we left."],"commonMistakes":["Because it was late is a dependent clause, not normally a standalone formal sentence. Its use as a conversational answer is a different context."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"punctuation","id":"commas-and-clause-relations","title":"Commas with clauses, lists and supplementary information","explanation":"Commas separate items, frame introductory material and set off supplements. They normally do not divide a subject from its predicate or a verb from its ordinary object. Relative-clause commas can change whether information identifies a referent or merely adds a comment. A serial comma is a house-style choice unless clarity requires restructuring.","pattern":"My neighbour, **who works nights**, is asleep.","examples":["After the meeting, **we went home**.","We invited **teachers, parents and students**."],"commonMistakes":["A pause in speech does not automatically require a comma. Grammar and intended grouping are more reliable than placing punctuation wherever you breathe."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"punctuation","id":"colons-semicolons-dashes","title":"Colons, semicolons and dashes","explanation":"A colon commonly introduces an explanation, expansion or list after a complete introductory clause. A semicolon links related independent clauses or separates complex list items. A dash can mark an interruption or added explanation more emphatically. Each mark signals a relationship; none is simply a decorative substitute for a comma.","pattern":"One problem remained: **the key was missing**.","examples":["The road was closed; **we took a detour**.","There was one answer—**leave immediately**."],"commonMistakes":["Do not routinely insert a colon between a verb and its direct object: We bought apples and pears needs no colon after bought."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"punctuation","id":"quotation-and-dialogue","title":"Quotation marks, reporting clauses and quoted punctuation","explanation":"Quotation marks distinguish exact wording from the surrounding report. A reporting clause can precede, interrupt or follow dialogue. Use capitals and sentence punctuation according to the quoted unit. British and American house styles differ in quotation marks and punctuation placement, especially when the punctuation is not part of the original quotation.","pattern":"She said, **“We are ready.”**","examples":["**“Are you ready?”** she asked.","He called the result **“unexpected”**."],"commonMistakes":["Do not convert a partial quotation into a full sentence merely because it is inside quotation marks. Match the punctuation to what is actually quoted."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"punctuation","id":"apostrophes-hyphens-brackets","title":"Apostrophes, hyphens, parentheses and ellipsis marks","explanation":"Apostrophes commonly mark possession or omitted letters, not ordinary plurals. Hyphens can clarify compound modifiers; parentheses enclose secondary information. An ellipsis mark can indicate omitted quoted material or a trailing utterance, but must not distort the source. These conventions work alongside the grammatical structure.","pattern":"a **well-known** writer · **its** cover / **it’s** open","examples":["The editor **(who had just arrived)** checked the text.","The report concerns **twenty-year-old buildings**."],"commonMistakes":["A compound modifier ending in a normal -ly adverb usually needs no hyphen: a carefully written letter. Hyphenation of established compounds can be dictionary- or house-style-specific."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"punctuation","id":"capitals-numerals-abbreviations","title":"Capitalisation, numbers, abbreviations and typography","explanation":"Capitalise sentence openings, the pronoun I and proper names, including languages and days. Generic nouns usually stay lower-case unless they form part of a name or title under the chosen style. Numerals, dates, abbreviated titles and headings have conventions that vary by purpose and region. Consistency makes a document easier to interpret.","pattern":"**Monday**, **English**, **I** · the **university**","examples":["She studies **French history**.","We met **Dr Patel** at the clinic."],"commonMistakes":["Capitalisation does not reliably identify a grammatical category: a common noun can begin a sentence, and brand names may use unconventional case."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["The train stopped**;** we got off.","We need three things**:** paper, ink and time.","She said, **“Please wait.”**","**It’s** Tuesday. / The dog lost **its** collar."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["noun-clauses"],"readingReferenceIds":["dfe-grammar","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='punctuation-clauses'
